    "perfecto",
    "genial",
    "me encanta",
    "s\xFAper",
    "incre\xEDble",
    "maravilloso",
    "hermoso",
    "ideal",
    "justo lo que",
    "exactamente",
    "me gusta",
    "interesante",
    "bien",
    "bueno",
    "gracias"
