    "caro",
    "no puedo",
    "no tengo",
    "malo",
    "dif\xEDcil",
    "complicado",
    "no me gusta",
    "no sirve",
    "decepcion",
    "molesto",
    "problema",
    "no funciona",
    "tarde",
    "lento",
    "mal",
